WITH filtered_accounts AS (SELECT * FROM accounts WHERE opened_date > '2024-05-12' AND account_type NOT IN ('SAVINGS', 'CREDIT', 'CHECKING')), accounts_stats AS (SELECT CASE WHEN balance >= 81000 THEN 'high' WHEN balance >= 15000 THEN 'mid' ELSE 'low' END AS balance_bucket, MAX(opened_date) AS last_opened_date, SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END) AS open_count FROM filtered_accounts GROUP BY CASE WHEN balance >= 81000 THEN 'high' WHEN balance >= 15000 THEN 'mid' ELSE 'low' END) SELECT * FROM accounts_stats WHERE open_count > 44 ORDER BY last_opened_date;
